const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9"; // 10" x 5.625"
pres.author = "HTTP Archive";
pres.title = "State of the Web 2020-2025";

// ── Color Palette: "Deep Network" ──
const C = {
  darkBg:    "0F172A",
  lightBg:   "F1F5F9",
  accent:    "0EA5E9",   // sky blue — desktop / primary
  cyan:      "06B6D4",   // cyan — mobile / secondary
  darkText:  "0F172A",
  lightText: "F8FAFC",
  muted:     "64748B",
  cardBg:    "FFFFFF",
  border:    "E2E8F0",
  green:     "10B981",
  amber:     "F59E0B",
  slate700:  "334155",
  slate800:  "1E293B",
};

// ── Chart data (trends from source_brief.md) ──
const timeLabels = ["Jan '20","Jul '20","Jan '21","Jul '21","Jan '22","Jul '22","Jan '23","Jul '23","Jan '24","Jan '25"];

const sampleDesktop = [5.0, 5.2, 5.5, 6.0, 8.0, 15.0, 15.5, 16.0, 16.0, 16.0];
const sampleMobile  = [3.5, 3.7, 4.0, 4.5, 6.0, 10.0, 11.0, 12.5, 12.5, 12.5];

const weightDesktop = [1600, 1650, 1700, 1750, 1800, 1850, 1900, 1950, 2000, 2000];
const weightMobile  = [1500, 1550, 1600, 1650, 1700, 1750, 1800, 1850, 1900, 1900];

const tcpDesktop = [15, 14.5, 14, 13.5, 13, 12.5, 12, 12, 12, 12];
const tcpMobile  = [15, 14, 13.5, 13, 12.5, 12, 11.5, 11, 11, 11];

const httpsDesktop = [80, 83, 87, 90, 93, 95, 97, 98, 99, 99.2];
const httpsMobile  = [80, 82, 86, 89, 92, 94, 96, 97, 98, 99.1];

// ── Helpers ──
const cardShadow = () => ({ type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.10 });

function addCard(slide, x, y, w, h, accentColor) {
  slide.addShape(pres.shapes.RECTANGLE, { x, y, w, h, fill: { color: C.cardBg }, shadow: cardShadow() });
  slide.addShape(pres.shapes.RECTANGLE, { x, y, w: 0.06, h, fill: { color: accentColor } });
}

// ═══════════════════════════════════════════════
// SLIDE 1 — TITLE
// ═══════════════════════════════════════════════
let s1 = pres.addSlide();
s1.background = { color: C.darkBg };

s1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent } });

s1.addText("State of the Web 2020–2025", {
  x: 0.8, y: 1.2, w: 8.4, h: 1.2,
  fontSize: 40, fontFace: "Arial Black", color: C.lightText, align: "left", margin: 0
});

s1.addText("HTTP Archive Trends in Page Weight, Protocols, and Security", {
  x: 0.8, y: 2.5, w: 8.4, h: 0.6,
  fontSize: 20, fontFace: "Calibri", color: C.accent, align: "left", margin: 0
});

s1.addShape(pres.shapes.LINE, {
  x: 0.8, y: 3.3, w: 2.0, h: 0, line: { color: C.accent, width: 2 }
});

s1.addText([
  { text: "Data Source: HTTP Archive — State of the Web Report", options: { breakLine: true } },
  { text: "Time Range: January 2020 – March 2026" }
], {
  x: 0.8, y: 3.6, w: 8.4, h: 0.8,
  fontSize: 14, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});

s1.addText("https://httparchive.org/reports/state-of-the-web", {
  x: 0.8, y: 4.5, w: 8.4, h: 0.3,
  fontSize: 11, fontFace: "Calibri", color: C.slate700, align: "left", margin: 0
});

// ═══════════════════════════════════════════════
// SLIDE 2 — CRAWL SAMPLE SIZE TRIPLED
// ═══════════════════════════════════════════════
let s2 = pres.addSlide();
s2.background = { color: C.lightBg };

s2.addText("Crawl Sample Size Tripled", {
  x: 0.6, y: 0.25, w: 6.5, h: 0.5,
  fontSize: 28, fontFace: "Arial Black", color: C.darkText, align: "left", margin: 0
});
s2.addText("From ~5M to 16M Desktop URLs Since 2020", {
  x: 0.6, y: 0.75, w: 6.5, h: 0.35,
  fontSize: 15, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});

// Dual-line time-series chart
s2.addChart(pres.charts.LINE, [
  { name: "Desktop", labels: timeLabels, values: sampleDesktop },
  { name: "Mobile",  labels: timeLabels, values: sampleMobile  }
], {
  x: 0.6, y: 1.3, w: 5.8, h: 3.4,
  chartColors: [C.accent, C.cyan],
  lineSize: 3,
  showLegend: true, legendPos: "b", legendFontSize: 10, legendColor: C.muted,
  catAxisLabelColor: C.muted, catAxisLabelFontSize: 8,
  valAxisLabelColor: C.muted, valAxisLabelFontSize: 9,
  valGridLine: { color: C.border, size: 0.5 },
  catGridLine: { style: "none" },
  showTitle: false,
  chartArea: { fill: { color: C.cardBg }, roundedCorners: true },
});

// Desktop stat card
addCard(s2, 6.8, 1.4, 2.8, 1.5, C.accent);
s2.addText("16M", {
  x: 7.05, y: 1.45, w: 2.4, h: 0.75,
  fontSize: 36, fontFace: "Arial Black", color: C.accent, align: "left", margin: 0
});
s2.addText("Desktop URLs", {
  x: 7.05, y: 2.2, w: 2.4, h: 0.3,
  fontSize: 12, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});
s2.addText("▲ 220% since Jan 2020", {
  x: 7.05, y: 2.5, w: 2.4, h: 0.3,
  fontSize: 10, fontFace: "Calibri", color: C.green, align: "left", margin: 0
});

// Mobile stat card
addCard(s2, 6.8, 3.1, 2.8, 1.5, C.cyan);
s2.addText("12.5M", {
  x: 7.05, y: 3.15, w: 2.4, h: 0.75,
  fontSize: 36, fontFace: "Arial Black", color: C.cyan, align: "left", margin: 0
});
s2.addText("Mobile URLs", {
  x: 7.05, y: 3.9, w: 2.4, h: 0.3,
  fontSize: 12, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});
s2.addText("▲ 257% since Jan 2020", {
  x: 7.05, y: 4.2, w: 2.4, h: 0.3,
  fontSize: 10, fontFace: "Calibri", color: C.green, align: "left", margin: 0
});

s2.addText("Sharp jump around mid-2022; plateau reached by mid-2023", {
  x: 0.6, y: 4.9, w: 5.8, h: 0.3,
  fontSize: 9, fontFace: "Calibri", color: C.muted, align: "left", italic: true, margin: 0
});

// ═══════════════════════════════════════════════
// SLIDE 3 — PAGE WEIGHT TRENDS
// ═══════════════════════════════════════════════
let s3 = pres.addSlide();
s3.background = { color: C.lightBg };

s3.addText("Median Page Weight Climbs Steadily", {
  x: 0.6, y: 0.25, w: 8.8, h: 0.5,
  fontSize: 28, fontFace: "Arial Black", color: C.darkText, align: "left", margin: 0
});
s3.addText("Desktop median now ~2,000 KB, up 25% from 2020 baseline", {
  x: 0.6, y: 0.75, w: 8.8, h: 0.35,
  fontSize: 15, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});

// Full-width line chart
s3.addChart(pres.charts.LINE, [
  { name: "Desktop", labels: timeLabels, values: weightDesktop },
  { name: "Mobile",  labels: timeLabels, values: weightMobile  }
], {
  x: 0.6, y: 1.2, w: 8.8, h: 2.8,
  chartColors: [C.accent, C.cyan],
  lineSize: 3,
  lineSmooth: true,
  showLegend: true, legendPos: "b", legendFontSize: 10, legendColor: C.muted,
  catAxisLabelColor: C.muted, catAxisLabelFontSize: 8,
  valAxisLabelColor: C.muted, valAxisLabelFontSize: 9,
  valGridLine: { color: C.border, size: 0.5 },
  catGridLine: { style: "none" },
  showTitle: false,
  chartArea: { fill: { color: C.cardBg }, roundedCorners: true },
});

// Bottom stat cards
addCard(s3, 0.6, 4.2, 4.2, 0.9, C.accent);
s3.addText("~2,000 KB", {
  x: 0.85, y: 4.25, w: 2.0, h: 0.45,
  fontSize: 22, fontFace: "Arial Black", color: C.accent, align: "left", margin: 0
});
s3.addText("Desktop median  ▲ 25% since 2020", {
  x: 0.85, y: 4.7, w: 3.8, h: 0.3,
  fontSize: 10, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});

addCard(s3, 5.1, 4.2, 4.2, 0.9, C.cyan);
s3.addText("~1,900 KB", {
  x: 5.35, y: 4.25, w: 2.0, h: 0.45,
  fontSize: 22, fontFace: "Arial Black", color: C.cyan, align: "left", margin: 0
});
s3.addText("Mobile median  ▲ 25%  |  75th pctile desktop > 4,000 KB", {
  x: 5.35, y: 4.7, w: 3.8, h: 0.3,
  fontSize: 10, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});

// ═══════════════════════════════════════════════
// SLIDE 4 — REQUESTS AND CONNECTIONS
// ═══════════════════════════════════════════════
let s4 = pres.addSlide();
s4.background = { color: C.lightBg };

s4.addText("76 Requests per Desktop Page While TCP Connections Drop to 12", {
  x: 0.6, y: 0.25, w: 8.8, h: 0.5,
  fontSize: 24, fontFace: "Arial Black", color: C.darkText, align: "left", margin: 0
});
s4.addText("More requests, fewer connections — multiplexing at work", {
  x: 0.6, y: 0.75, w: 8.8, h: 0.35,
  fontSize: 15, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});

// LEFT: Request stat cards
addCard(s4, 0.6, 1.3, 3.8, 1.35, C.accent);
s4.addText("76", {
  x: 0.85, y: 1.35, w: 1.5, h: 0.7,
  fontSize: 42, fontFace: "Arial Black", color: C.accent, align: "left", margin: 0
});
s4.addText([
  { text: "Requests / Page (Desktop)", options: { breakLine: true } },
  { text: "▲ 2.7% since 2020", options: {} }
], {
  x: 0.85, y: 2.1, w: 3.3, h: 0.5,
  fontSize: 11, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});

addCard(s4, 0.6, 2.85, 3.8, 1.35, C.cyan);
s4.addText("71", {
  x: 0.85, y: 2.9, w: 1.5, h: 0.7,
  fontSize: 42, fontFace: "Arial Black", color: C.cyan, align: "left", margin: 0
});
s4.addText([
  { text: "Requests / Page (Mobile)", options: { breakLine: true } },
  { text: "▲ 2.9% since 2020", options: {} }
], {
  x: 0.85, y: 3.65, w: 3.3, h: 0.5,
  fontSize: 11, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});

// RIGHT: TCP connections declining chart
s4.addChart(pres.charts.LINE, [
  { name: "Desktop", labels: timeLabels, values: tcpDesktop },
  { name: "Mobile",  labels: timeLabels, values: tcpMobile  }
], {
  x: 4.8, y: 1.2, w: 4.8, h: 3.2,
  chartColors: [C.accent, C.cyan],
  lineSize: 3,
  lineSmooth: true,
  showLegend: true, legendPos: "b", legendFontSize: 10, legendColor: C.muted,
  catAxisLabelColor: C.muted, catAxisLabelFontSize: 8,
  valAxisLabelColor: C.muted, valAxisLabelFontSize: 9,
  valGridLine: { color: C.border, size: 0.5 },
  catGridLine: { style: "none" },
  showTitle: true,
  title: "TCP Connections per Page (Declining)",
  titleColor: C.slate700,
  titleFontSize: 11,
  chartArea: { fill: { color: C.cardBg }, roundedCorners: true },
});

// Bottom insight bar
addCard(s4, 0.6, 4.6, 9.0, 0.65, C.green);
s4.addText("TCP connections fell 14.3% (desktop) and 26.7% (mobile) — HTTP/2 and HTTP/3 multiplexing allow many requests over fewer connections", {
  x: 0.9, y: 4.65, w: 8.5, h: 0.55,
  fontSize: 11, fontFace: "Calibri", color: C.slate700, align: "left", valign: "middle", margin: 0
});

// ═══════════════════════════════════════════════
// SLIDE 5 — HTTPS NEAR UNIVERSAL
// ═══════════════════════════════════════════════
let s5 = pres.addSlide();
s5.background = { color: C.lightBg };

s5.addText("HTTPS Requests Reach 99%", {
  x: 0.6, y: 0.25, w: 8.8, h: 0.5,
  fontSize: 28, fontFace: "Arial Black", color: C.darkText, align: "left", margin: 0
});
s5.addText("Encryption Is Now the Default", {
  x: 0.6, y: 0.75, w: 8.8, h: 0.35,
  fontSize: 15, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});

// LEFT: Large stat callout
addCard(s5, 0.6, 1.4, 4.0, 3.3, C.accent);

s5.addText("99%+", {
  x: 0.9, y: 1.55, w: 3.5, h: 1.2,
  fontSize: 64, fontFace: "Arial Black", color: C.accent, align: "center", valign: "middle", margin: 0
});

s5.addText([
  { text: "99.2%  Desktop requests", options: { breakLine: true } },
  { text: "99.1%  Mobile requests", options: { breakLine: true } },
  { text: "", options: { breakLine: true } },
  { text: "▲ 19–20 percentage points since 2020", options: {} }
], {
  x: 0.9, y: 2.9, w: 3.5, h: 1.5,
  fontSize: 13, fontFace: "Calibri", color: C.slate700, align: "center", valign: "top", margin: 0
});

// RIGHT: Small time-series chart
s5.addChart(pres.charts.LINE, [
  { name: "Desktop", labels: timeLabels, values: httpsDesktop },
  { name: "Mobile",  labels: timeLabels, values: httpsMobile  }
], {
  x: 5.0, y: 1.4, w: 4.6, h: 3.3,
  chartColors: [C.accent, C.cyan],
  lineSize: 3,
  lineSmooth: true,
  showLegend: true, legendPos: "b", legendFontSize: 10, legendColor: C.muted,
  catAxisLabelColor: C.muted, catAxisLabelFontSize: 8,
  valAxisLabelColor: C.muted, valAxisLabelFontSize: 9,
  valGridLine: { color: C.border, size: 0.5 },
  catGridLine: { style: "none" },
  showTitle: true,
  title: "HTTPS Adoption Over Time",
  titleColor: C.slate700,
  titleFontSize: 11,
  chartArea: { fill: { color: C.cardBg }, roundedCorners: true },
});

s5.addText("Plaintext HTTP is effectively extinct on the modern web", {
  x: 0.6, y: 4.9, w: 9.0, h: 0.3,
  fontSize: 11, fontFace: "Calibri", color: C.green, align: "left", italic: true, margin: 0
});

// ═══════════════════════════════════════════════
// SLIDE 6 — HTTP/2 vs HTTP/3
// ═══════════════════════════════════════════════
let s6 = pres.addSlide();
s6.background = { color: C.lightBg };

s6.addText("HTTP/2 Holds at ~58% While HTTP/3 Support Surges to 40%", {
