  x: 0.6, y: 0.25, w: 8.8, h: 0.5,
  fontSize: 28, fontFace: "Arial Black", color: C.darkText, align: "left", margin: 0
});
s7.addText("Up 61% since 2020 — but more than half of pages still risk FOIT", {
  x: 0.6, y: 0.75, w: 8.8, h: 0.35,
  fontSize: 15, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});

// Bar chart: current adoption
s7.addChart(pres.charts.BAR, [
