});

// Growth annotations below chart
s7.addText("Desktop: ▲ 14.9% since 2020    |    Mobile: ▲ 61.0% since 2020", {
  x: 0.6, y: 4.55, w: 5.5, h: 0.3,
  fontSize: 10, fontFace: "Calibri", color: C.slate700, align: "center", italic: true, margin: 0
});

// Right: Explanation card
addCard(s7, 6.5, 1.3, 3.1, 1.8, C.amber);
s7.addText("What is font-display?", {
  x: 6.8, y: 1.35, w: 2.6, h: 0.4,
  fontSize: 14, fontFace: "Arial Black", color: C.slate800, align: "left", margin: 0
});
s7.addText("The font-display CSS property controls how web fonts render during loading, helping avoid the Flash of Invisible Text (FOIT). Without it, users may see blank text while fonts load.", {
  x: 6.8, y: 1.8, w: 2.6, h: 1.15,
  fontSize: 10, fontFace: "Calibri", color: C.slate700, align: "left", valign: "top", margin: 0
});

// Dark callout card
s7.addShape(pres.shapes.RECTANGLE, { x: 6.5, y: 3.3, w: 3.1, h: 1.25, fill: { color: C.darkBg } });
s7.addText("58% of pages", {
  x: 6.7, y: 3.35, w: 2.7, h: 0.5,
  fontSize: 22, fontFace: "Arial Black", color: C.amber, align: "center", valign: "middle", margin: 0
});
s7.addText("still don’t use font-display", {
  x: 6.7, y: 3.85, w: 2.7, h: 0.35,
  fontSize: 11, fontFace: "Calibri", color: C.lightText, align: "center", valign: "top", margin: 0
});

// ═══════════════════════════════════════════════
