tyle: \"none\" },\n  showTitle: true,\n  title: \"TCP Connections per Page (Declining)\",\n  titleColor: C.slate700,\n  titleFontSize: 11,\n  chartArea: { fill: { color: C.cardBg }, roundedCorners: true },\n});\n\n// Bottom insight bar\naddCard(s4, 0.6, 4.6, 9.0, 0.65, C.green);\ns4.addText(\"TCP connections fell 14.3% (desktop) and 26.7% (mobile) — HTTP/2 and HTTP/3 multiplexing allow many requests over fewer connections\", {\n  x: 0.9, y: 4.65, w: 8.5, h: 0.55,\n  fontSize: 11, fontFace: \"Calibri\", color: C.slate700, align: \"left\", valign: \"middle\", margin: 0\n});\n\n// ═══════════════════════════════════════════════\n// SLIDE 5 — HTTPS NEAR UNIVERSAL\n// ═══════════════════════════════════════════════\nlet s5 = pres.addSlide();\ns5.background = { color: C.lightBg };\n\ns5.addText(\"HTTPS Requests Reach 99%\", {\n  x: 0.6, y: 0.25, w: 8.8, h: 0.5,\n  fontSize: 28, fontFace: \"Arial Black\", color: C.darkText, align: \"left\", margin: 0\n});\ns5.addText(\"Encryption Is Now the Default\", {\n  x: 0.6, y: 0.75, w: 8.8, h: 0.35,\n  fontSize: 15, fontFace: \"Calibri\", color: C.muted, align: \"left\", margin: 0\n});\n\n// LEFT: Large stat callout\naddCard(s5, 0.6, 1.4, 4.0, 3.3, C.accent);\n\ns5.addText(\"99%+\", {\n  x: 0.9, y: 1.55, w: 3.5, h: 1.2,\n  fontSize: 64, fontFace: \"Arial Black\", color: C.accent, align: \"center\", valign: \"middle\", margin: 0\n});\n\ns5.addText([\n  { text: \"99.2%  Desktop requests\", options: { breakLine: true } },\n  { text: \"99.1%  Mobile requests\", options: { breakLine: true } },\n  { text: \"\", options: { breakLine: true } },\n  { text: \"▲ 19–20 percentage points since 2020\", options: {} }\n], {\n  x: 0.9, y: 2.9, w: 3.5, h: 1.5,\n  fontSize: 13, fontFace: \"Calibri\", color: C.slate700, align: \"center\", valign: \"top\", margin: 0\n});\n\n// RIGHT: Small time-series chart\ns5.addChart(pres.charts.LINE, [\n  { name: \"Desktop\", labels: timeLabels, values: httpsDesktop },\n  { name: \"Mobile\",  labels: timeLabels, values: httpsMobile  }\n], {\n  x: 5.0, y: 1.4, w: 4.6, h: 3.3,\n  chartColors: [C.accent, C.cyan],\n  lineSize: 3,\n  lineSmooth: true,\n  showLegend: true, legendPos: \"b\", legendFontSize: 10, legendColor: C.muted,\n  catAxisLabelColor: C.muted, catAxisLabelFontSize: 8,\n  valAxisLabelColor: C.muted, valAxisLabelFontSize: 9,\n  valGridLine: { color: C.border, size: 0.5 },\n  catGridLine: { style: \"none\" },\n  showTitle: true,\n  title: \"HTTPS Adoption Over Time\",\n  titleColor: C.slate700,\n  titleFontSize: 11,\n  chartArea: { fill: { color: C.cardBg }, roundedCorners: true },\n});\n\ns5.addText(\"Plaintext HTTP is effectively extinct on the modern web\", {\n  x: 0.6, y: 4.9, w: 9.0, h: 0.3,\n  fontSize: 11, fontFace: \"Calibri\", color: C.green, align: \"left\", italic: true, margin: 0\n});\n\n// ═══════════════════════════════════════════════\n// SLIDE 6 — HTTP/2 vs HTTP/3\n// ═══════════════════════════════════════════════\nlet s6 = pres.addSlide();\ns6.background = { color: C.lightBg };\n\ns6.addText(\"HTTP/2 Holds at ~58% While HTTP/3 Support Surges to 40%\", {\n  x: 0.6, y: 0.25, w: 8.8, h: 0.5,\n  fontSize: 24, fontFace: \"Arial Black\", color: C.darkText, align: \"left\", margin: 0\n});\ns6.addText(\"Protocol adoption snapshot — the web transitions to next-generation protocols\", {\n  x: 0.6, y: 0.75, w: 8.8, h: 0.35,\n  fontSize: 15, fontFace: \"Calibri\", color: C.muted, align: \"left\", margin: 0\n});\n\n// Grouped bar chart\ns6.addChart(pres.charts.BAR, [\n  { name: \"Desktop\", labels: [\"HTTP/2 Requests\", \"HTTP/3 Support\"], values: [58.6, 38.7] },\n  { name: \"Mobile\",  labels: [\"HTTP/2 Requests\", \"HTTP/3 Support\"], values: [57.6, 40.0] }\n], {\n  x: 0.6, y: 1.2, w: 5.0, h: 3.2,\n  barDir: \"col\",\n  chartColors: [C.accent, C.cyan],\n  showValue: true, dataLabelPosition: \"outEnd\", dataLabelColor: C.slate800, dataLabelFontSize: 11,\n  catAxisLabelColor: C.slate700, catAxisLabelFontSize: 11,\n  valAxisLabelColor: C.muted, valAxisLabelFontSize: 9,\n  valGridLine: { color: C.border, size: 0.5 },\n  catGridLine: { style: \"none\" },\n  showLegend: true, legendPos: \"b\", legendFontSize: 10, legendColor: C.muted,\n  showTitle: false,\n  chartArea: { fill: { color: C.cardBg }, roundedCorners: true },\n  valAxisMaxVal: 70,\n});\n\n// HTTP/2 info card\naddCard(s6, 6.0, 1.3, 3.6, 1.3, C.accent);\ns6.addText(\"HTTP/2\", {\n  x: 6.3, y: 1.35, w: 3.1, h: 0.4,\n  fontSize: 16, fontFace: \"Arial Black\", color: C.accent, align: \"left\", margin: 0\n});\ns6.addText([\n  { text: \"58.6% desktop / 57.6% mobile\", options: { breakLine: true } },\n  { text: \"Growth modest (1–3%); HTTP/3 absorbs newer adoption\", options: {} }\n], {\n  x: 6.3, y: 1.8, w: 3.1, h: 0.7,\n  fontSize: 10, fontFace: \"Calibri\", color: C.slate700, align: \"left\", margin: 0\n});\n\n// HTTP/3 info card\naddCard(s6, 6.0, 2.8, 3.6, 1.3, C.cyan);\ns6.addText(\"HTTP/3\", {\n  x: 6.3, y: 2.85, w: 3.1, h: 0.4,\n  fontSize: 16, fontFace: \"Arial Black\", color: C.cyan, align: \"left\", margin: 0\n});\ns6.addText([\n  { text: \"38.7% desktop / 40.0% mobile\", options: { breakLine: true } },\n  { text: \"Explosive growth from near-zero — fastest-growing protocol metric\", options: {} }\n], {\n  x: 6.3, y: 3.3, w: 3.1, h: 0.7,\n  fontSize: 10, fontFace: \"Calibri\", color: C.slate700, align: \"left\", margin: 0\n});\n\n// Caveat bar\naddCard(s6, 0.6, 4.6, 9.0, 0.65, C.amber);\ns6.addText(\"HTTP Archive measures HTTP/3 support, not actual usage — fresh Chrome instances default to HTTP/2 before discovering HTTP/3 via Alt-Svc headers\", {\n  x: 0.9, y: 4.65, w: 8.5, h: 0.55,\n  fontSize: 10, fontFace: \"Calibri\", color: C.slate700, align: \"left\", valign: \"middle\", margin: 0\n});\n\n// ═══════════════════════════════════════════════\n// SLIDE 7 — FONT-DISPLAY ADOPTION\n// ═══════════════════════════════════════════════\nlet s7 = pres.addSlide();\ns7.background = { color: C.lightBg };\n\ns7.addText(\"Font-Display Usage Reaches 42% on Mobile\", {\n  x: 0.6, y: 0.25, w: 8.8, h: 0.5,\n  fontSize: 28, fontFace: \"Arial Black\", color: C.darkText, align: \"left\", margin: 0\n});\ns7.addText(\"Up 61% since 2020 — but more than half of pages still risk FOIT\", {\n  x: 0.6, y: 0.75, w: 8.8, h: 0.35,\n  fontSize: 15, fontFace: \"Calibri\", color: C.muted, align: \"left\", margin: 0\n});\n\n// Bar chart: current adoption\ns7.addChart(pres.charts.BAR, [\n  { name: \"Current Adoption\", labels: [\"Desktop\", \"Mobile\"], values: [40.1, 42.5] }\n], {\n  x: 0.6, y: 1.2, w: 5.5, h: 3.2,\n  barDir: \"col\",\n  chartColors: [C.accent],\n  showValue: true, dataLabelPosition: \"outEnd\", dataLabelColor: C.slate800, dataLabelFontSize: 12,\n  catAxisLabelColor: C.slate700, catAxisLabelFontSize: 12,\n  valAxisLabelColor: C.muted, valAxisLabelFontSize: 9,\n  valGridLine: { color: C.border, size: 0.5 },\n  catGridLine: { style: \"none\" },\n  showLegend: false,\n  showTitle: false,\n  chartArea: { fill: { color: C.cardBg }, roundedCorners: true },\n  valAxisMaxVal: 60,\n});\n\n// Growth annotations below chart\ns7.addText(\"Desktop: ▲ 14.9% since 2020    |    Mobile: ▲ 61.0% since 2020\", {\n  x: 0.6, y: 4.55, w: 5.5, h: 0.3,\n  fontSize: 10, fontFace: \"Calibri\", color: C.slate700, align: \"center\", italic: true, margin: 0\n});\n\n// Right: Explanation card\naddCard(s7, 6.5, 1.3, 3.1, 1.8, C.amber);\ns7.addText(\"What is font-display?\", {\n  x: 6.8, y: 1.35, w: 2.6, h: 0.4,\n  fontSize: 14, fontFace: \"Arial Black\", color: C.slate800, align: \"left\", margin: 0\n});\ns7.addText(\"The font-display CSS property controls how web fonts render during loading, helping avoid the Flash of Invisible Text (FOIT). Without it, users may see blank text while fonts load.\", {\n  x: 6.8, y: 1.8, w: 2.6, h: 1.15,\n  fontSize: 10, fontFace: \"Calibri\", color: C.slate700, align: \"left\", valign: \"top\", margin: 0\n});\n\n// Dark callout card\ns7.addShape(pres.shapes.RECTANGLE, { x: 6.5, y: 3.3, w: 3.1, h: 1.25, fill: { color: C.darkBg } });\ns7.addText(\"58% of pages\", {\n  x: 6.7, y: 3.35, w: 2.7, h: 0.5,\n  fontSize: 22, fontFace: \"Arial Black\", color: C.amber, align: \"center\", valign: \"middle\", margin: 0\n});\ns7.addText(\"still don’t use font-display\", {\n  x: 6.7, y: 3.85, w: 2.7, h: 0.35,\n  fontSize: 11, fontFace: \"Calibri\", color: C.lightText, align: \"center\", valign: \"top\", margin: 0\n});\n\n// ═══════════════════════════════════════════════\n// SLIDE 8 — KEY TAKEAWAYS\n// ═══════════════════════════════════════════════\nlet s8 = pres.addSlide();\ns8.background = { color: C.darkBg };\n\ns8.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent } });\n\ns8.addText(\"Key Takeaways\", {\n  x: 0.8, y: 0.3, w: 8.4, h: 0.6,\n  fontSize: 32, fontFace: \"Arial Black\", color: C.lightText, align: \"left\", margin: 0\n});\ns8.addText(\"Bigger Pages, Smarter Protocols, Stronger Security\", {\n  x: 0.8, y: 0.9, w: 8.4, h: 0.4,\n  fontSize: 16, fontFace: \"Calibri\", color: C.accent, align: \"left\", margin: 0\n});\n\nconst takeaways = [\n  { title: \"Page weight keeps climbing\", detail: \"Median desktop pages now transfer ~2,000 KB, roughly 25% heavier than 2020, driven by richer media and JavaScript.\" },\n  { title: \"HTTPS is the new baseline\", detail: \"At 99%+ of requests, unencrypted HTTP is essentially extinct on the modern web.\" },\n  { title: \"HTTP/3 is the fastest-growing protocol metric\", detail: \"From near-zero to ~40% support in under four years, HTTP/3 is rapidly becoming mainstream.\" },\n  { title: \"Fewer TCP connections despite more requests\", detail: \"Multiplexing in HTTP/2 and HTTP/3 has cut median connections per page by 15–27%.\" },\n  { title: \"Font-display still underused\", detail: \"At ~40–42% adoption, significant room remains for improvement in avoiding invisible text during font loading.\" },\n];\n\ntakeaways.forEach((t, i) => {\n  const yPos = 1.6 + i * 0.7;\n\n  s8.addShape(pres.shapes.OVAL, {\n    x: 0.8, y: yPos, w: 0.35, h: 0.35,\n    fill: { color: C.accent }\n  });\n  s8.addText(String(i + 1), {\n    x: 0.8, y: yPos, w: 0.35, h: 0.35,\n    fontSize: 12, fontFace: \"Arial Black\", color: C.lightText,\n    align: \"center\", valign: \"middle\", margin: 0\n  });\n\n  s8.addText([\n    { text: t.title, options: { bold: true, breakLine: true } },\n    { text: t.detail, options: {} }\n  ], {\n    x: 1.35, y: yPos - 0.05, w: 7.8, h: 0.65,\n    fontSize: 11, fontFace: \"Calibri\", color: C.lightText,\n    align: \"left\", valign: \"top\", margin: 0\n  });\n});\n\n// CTA\ns8.addShape(pres.shapes.RECTANGLE, {\n  x: 0.8, y: 5.1, w: 8.4, h: 0.04, fill: { color: C.accent }\n});\ns8.addText(\"Benchmark your own sites against these baselines — httparchive.org/reports/state-of-the-web\", {\n  x: 0.8, y: 4.65, w: 8.4, h: 0.4,\n  fontSize: 13, fontFace: \"Calibri\", color: C.accent, align: \"left\", bold: true, margin: 0\n});\n\n// ── Save ──\npres.writeFile({ fileName: \"/app/output/final_deck.pptx\" })\n  .then(() => console.log(\"Saved: /app/output/final_deck.pptx\"))\n  .catch(err => console.error(\"Error:\", err));\n", "numLines": 524, "startLine": 1, "totalLines": 524}}

