const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9"; // 10" x 5.625"
pres.author = "HTTP Archive";
pres.title = "State of the Web 2020-2025";

// ── Color Palette: "Deep Network" ──
const C = {
  darkBg:    "0F172A",
  lightBg:   "F1F5F9",
  accent:    "0EA5E9",
  cyan:      "06B6D4",
  darkText:  "0F172A",
  lightText: "F8FAFC",
  muted:     "64748B",
  mutedLt:   "94A3B8",   // lighter muted for dark bg contrast
  cardBg:    "FFFFFF",
  border:    "E2E8F0",
  green:     "10B981",
  amber:     "F59E0B",
  slate700:  "334155",
  slate800:  "1E293B",
};

// ── Chart data (trends from source_brief.md) ──
const timeLabels = ["Jan '20","Jul '20","Jan '21","Jul '21","Jan '22","Jul '22","Jan '23","Jul '23","Jan '24","Jan '25"];

const sampleDesktop = [5.0, 5.2, 5.5, 6.0, 8.0, 15.0, 15.5, 16.0, 16.0, 16.0];
const sampleMobile  = [3.5, 3.7, 4.0, 4.5, 6.0, 10.0, 11.0, 12.5, 12.5, 12.5];

const weightDesktop = [1600, 1650, 1700, 1750, 1800, 1850, 1900, 1950, 2000, 2000];
const weightMobile  = [1500, 1550, 1600, 1650, 1700, 1750, 1800, 1850, 1900, 1900];

const tcpDesktop = [15, 14.5, 14, 13.5, 13, 12.5, 12, 12, 12, 12];
const tcpMobile  = [15, 14, 13.5, 13, 12.5, 12, 11.5, 11, 11, 11];

const httpsDesktop = [80, 83, 87, 90, 93, 95, 97, 98, 99, 99.2];
const httpsMobile  = [80, 82, 86, 89, 92, 94, 96, 97, 98, 99.1];

// ── Helpers ──
const cardShadow = () => ({ type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.10 });

function addCard(slide, x, y, w, h, accentColor) {
  slide.addShape(pres.shapes.RECTANGLE, { x, y, w, h, fill: { color: C.cardBg }, shadow: cardShadow() });
  slide.addShape(pres.shapes.RECTANGLE, { x, y, w: 0.06, h, fill: { color: accentColor } });
}

// ═══════════════════════════════════════════════
// SLIDE 1 — TITLE
// ═══════════════════════════════════════════════
let s1 = pres.addSlide();
s1.background = { color: C.darkBg };

s1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent } });

s1.addText("State of the Web 2020–2025", {
  x: 0.8, y: 1.2, w: 8.4, h: 1.0,
  fontSize: 40, fontFace: "Arial Black", color: C.lightText, align: "left", margin: 0
});

s1.addText("HTTP Archive Trends in Page Weight, Protocols, and Security", {
  x: 0.8, y: 2.5, w: 8.4, h: 0.6,
  fontSize: 20, fontFace: "Calibri", color: C.accent, align: "left", margin: 0
});

s1.addShape(pres.shapes.LINE, {
  x: 0.8, y: 3.3, w: 2.0, h: 0, line: { color: C.accent, width: 2 }
});

// FIX: Use mutedLt for better contrast on dark bg (was C.muted @ 3.75:1)
s1.addText([
  { text: "Data Source: HTTP Archive — State of the Web Report", options: { breakLine: true } },
  { text: "Time Range: January 2020 – March 2026" }
], {
  x: 0.8, y: 3.6, w: 8.4, h: 0.7,
  fontSize: 14, fontFace: "Calibri", color: C.mutedLt, align: "left", margin: 0
});

// FIX: Use mutedLt instead of slate700 (was 1.72:1 contrast on dark bg)
s1.addText("https://httparchive.org/reports/state-of-the-web", {
  x: 0.8, y: 4.4, w: 8.4, h: 0.3,
  fontSize: 11, fontFace: "Calibri", color: C.mutedLt, align: "left", margin: 0
});

// ═══════════════════════════════════════════════
// SLIDE 2 — CRAWL SAMPLE SIZE TRIPLED
// ═══════════════════════════════════════════════
let s2 = pres.addSlide();
s2.background = { color: C.lightBg };

s2.addText("Crawl Sample Size Tripled", {
  x: 0.6, y: 0.35, w: 6.5, h: 0.5,
  fontSize: 28, fontFace: "Arial Black", color: C.darkText, align: "left", margin: 0
});
s2.addText("From ~5M to 16M Desktop URLs Since 2020", {
  x: 0.6, y: 0.85, w: 6.5, h: 0.35,
  fontSize: 15, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});

// Dual-line time-series chart
s2.addChart(pres.charts.LINE, [
  { name: "Desktop", labels: timeLabels, values: sampleDesktop },
  { name: "Mobile",  labels: timeLabels, values: sampleMobile  }
], {
  x: 0.6, y: 1.4, w: 5.6, h: 3.2,
  chartColors: [C.accent, C.cyan],
  lineSize: 3,
  showLegend: true, legendPos: "b", legendFontSize: 10, legendColor: C.muted,
  catAxisLabelColor: C.muted, catAxisLabelFontSize: 8,
  valAxisLabelColor: C.muted, valAxisLabelFontSize: 9,
  valGridLine: { color: C.border, size: 0.5 },
  catGridLine: { style: "none" },
  showTitle: false,
  chartArea: { fill: { color: C.cardBg }, roundedCorners: true },
});

// Desktop stat card — shifted left to give 0.5" right margin
addCard(s2, 6.5, 1.5, 2.9, 1.4, C.accent);
s2.addText("16M", {
  x: 6.75, y: 1.55, w: 2.5, h: 0.65,
  fontSize: 34, fontFace: "Arial Black", color: C.accent, align: "left", margin: 0
});
s2.addText("Desktop URLs", {
  x: 6.75, y: 2.2, w: 2.5, h: 0.25,
  fontSize: 12, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});
s2.addText("▲ 220% since Jan 2020", {
  x: 6.75, y: 2.48, w: 2.5, h: 0.25,
  fontSize: 10, fontFace: "Calibri", color: C.green, align: "left", margin: 0
});

// Mobile stat card — added 0.3" gap between cards
addCard(s2, 6.5, 3.1, 2.9, 1.4, C.cyan);
s2.addText("12.5M", {
  x: 6.75, y: 3.15, w: 2.5, h: 0.65,
  fontSize: 34, fontFace: "Arial Black", color: C.cyan, align: "left", margin: 0
});
s2.addText("Mobile URLs", {
  x: 6.75, y: 3.8, w: 2.5, h: 0.25,
  fontSize: 12, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});
s2.addText("▲ 257% since Jan 2020", {
  x: 6.75, y: 4.08, w: 2.5, h: 0.25,
  fontSize: 10, fontFace: "Calibri", color: C.green, align: "left", margin: 0
});

s2.addText("Sharp jump around mid-2022; plateau reached by mid-2023", {
  x: 0.6, y: 4.8, w: 5.6, h: 0.3,
  fontSize: 9, fontFace: "Calibri", color: C.muted, align: "left", italic: true, margin: 0
});

// ═══════════════════════════════════════════════
// SLIDE 3 — PAGE WEIGHT TRENDS
// ═══════════════════════════════════════════════
let s3 = pres.addSlide();
s3.background = { color: C.lightBg };

s3.addText("Median Page Weight Climbs Steadily", {
  x: 0.6, y: 0.35, w: 8.8, h: 0.5,
  fontSize: 28, fontFace: "Arial Black", color: C.darkText, align: "left", margin: 0
});
s3.addText("Desktop median now ~2,000 KB, up 25% from 2020 baseline", {
  x: 0.6, y: 0.85, w: 8.8, h: 0.35,
  fontSize: 15, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});

// Full-width line chart — added 0.1" gap after subtitle
s3.addChart(pres.charts.LINE, [
  { name: "Desktop", labels: timeLabels, values: weightDesktop },
  { name: "Mobile",  labels: timeLabels, values: weightMobile  }
], {
  x: 0.6, y: 1.3, w: 8.8, h: 2.6,
  chartColors: [C.accent, C.cyan],
  lineSize: 3,
  lineSmooth: true,
  showLegend: true, legendPos: "b", legendFontSize: 10, legendColor: C.muted,
  catAxisLabelColor: C.muted, catAxisLabelFontSize: 8,
  valAxisLabelColor: C.muted, valAxisLabelFontSize: 9,
  valGridLine: { color: C.border, size: 0.5 },
  catGridLine: { style: "none" },
  showTitle: false,
  chartArea: { fill: { color: C.cardBg }, roundedCorners: true },
});

// Bottom stat cards — 0.3" gap from chart
addCard(s3, 0.6, 4.2, 4.2, 0.8, C.accent);
s3.addText("~2,000 KB", {
  x: 0.85, y: 4.25, w: 2.0, h: 0.4,
  fontSize: 20, fontFace: "Arial Black", color: C.accent, align: "left", margin: 0
});
s3.addText("Desktop median  ▲ 25% since 2020", {
  x: 0.85, y: 4.65, w: 3.8, h: 0.3,
  fontSize: 10, fontFace: "Calibri", color: C.muted, align: "left", margin: 0
});

